        if all(self.condition_has_been_met):
            return True

        # Locate the first active stage: incomplete and unlocked
        for i, condition_set in enumerate(self.condition_sets):
            if self.condition_has_been_met[i]:
                continue
            if not self._is_unlocked(i):
